/** Reproduce the pinned, MIT-licensed offline ArrayBuffer parser used by the miniapp. */
const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const {createRequire}=require('node:module');
const root=path.resolve(__dirname,'..');const req=createRequire(path.join(root,'apps/miniapp-staff/package.json'));const pkg=req.resolve('exifr/package.json');const dir=path.dirname(pkg);const manifest=JSON.parse(fs.readFileSync(pkg,'utf8'));if(manifest.version!=='7.1.3')throw Error('Unexpected exifr version');
const source=fs.readFileSync(path.join(dir,'dist/full.umd.js'));const target=path.join(root,'apps/miniapp-staff/miniprogram/utils/vendor');fs.mkdirSync(target,{recursive:true});
// WeChat does not promise a browser self global. This module-local binding adds no global state.
fs.writeFileSync(path.join(target,'exifr.js'),'/* exifr 7.1.3 MIT; generated by tools/build-meter-exif.cjs; offline ArrayBuffer input only. */\nvar self = typeof globalThis === "object" ? globalThis : {};\n'+source.toString().replace(/\/\/# sourceMappingURL=.*$/m,''));
fs.copyFileSync(path.join(dir,'LICENSE'),path.join(target,'exifr.LICENSE.txt'));
fs.writeFileSync(path.join(target,'exifr.d.ts'),'export function parse(input: ArrayBuffer | Uint8Array, options?: Record<string, unknown>): Promise<Record<string, any> | undefined>;\n');
fs.writeFileSync(path.join(target,'exifr.NOTICE.md'),'# exifr 7.1.3\n\nUpstream: https://github.com/MikeKovarik/exifr\nLicense: MIT (exifr.LICENSE.txt).\nOriginal full.umd.js SHA256: '+crypto.createHash('sha256').update(source).digest('hex')+'\n\nOnly adaptation: module-local self binding for WeChat. Never pass paths, URLs or user identifiers; caller supplies bytes from the selected original photo. Rebuild with node tools/build-meter-exif.cjs after pnpm install.\n');
console.log('Pinned offline EXIF parser generated');
